import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import api from '../api/api';

export default function StationList() {
  const [stations, setStations] = useState([]);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!navigator.geolocation) {
      setError('Geolocation is not supported by your browser');
      setLoading(false);
      return;
    }

    navigator.geolocation.getCurrentPosition(
      async (position) => {
        const { latitude, longitude } = position.coords;
        try {
          const { data } = await api.get('/stations/nearby', {
            params: { lat: latitude, lng: longitude, radius: 500000 },
          });
          setStations(data);
        } catch (err) {
          setError(err.response?.data?.message || 'Could not load stations');
        } finally {
          setLoading(false);
        }
      },
      () => {
        setError('Location access denied. Enable location to find nearby stations.');
        setLoading(false);
      }
    );
  }, []);

  if (loading) return <p>Finding stations near you...</p>;
  if (error) return <p className="error">{error}</p>;

  return (
    <div className="station-list">
      <h2>Charging stations near you</h2>
      {stations.length === 0 && <p>No stations found nearby.</p>}
      {stations.map((s) => (
        <Link key={s._id} to={`/stations/${s._id}`} className="station-card">
          <h3>{s.name}</h3>
          <p>{s.address}</p>
          <p>₹{s.pricePerKwh} / kWh</p>
        </Link>
      ))}
    </div>
  );
}
